-- Initial reviewed catalogue supplied by the Marginal Economics team.
-- Exact term/definition matches are skipped so this migration is safe to retry.
WITH supplied(term, definition_text) AS (VALUES
  ('Scarcity', 'the fundamental economic problem that resources are finite/limited while human wants are unlimited.'),
  ('Wants', 'desires for goods and services that give satisfaction; they are unlimited.'),
  ('Resources (factors of production)', 'the inputs used to produce goods and services: land, labour, capital and enterprise.'),
  ('Choice', 'the act of selecting between alternative uses of scarce resources, made necessary by scarcity.'),
  ('Opportunity cost', 'the value of the next best alternative forgone when a choice is made.'),
  ('Resource allocation', 'the process of deciding how scarce resources are distributed among competing uses.'),
  ('What to produce', 'the decision about which goods and services, and in what quantities, should be produced.'),
  ('How to produce', 'the decision about which methods/combinations of factors of production to use.'),
  ('For whom to produce', 'the decision about how output is distributed among members of society.'),
  ('Economics', 'the social science that studies how scarce resources are allocated to satisfy unlimited wants.'),
  ('Social science', 'a discipline that studies human behaviour and society using scientific methods, but where controlled experiments are rarely possible.'),
  ('Positive statement', 'a statement of fact that can be tested/verified against evidence (what is).'),
  ('Normative statement', 'a statement involving a value judgement that cannot be scientifically proven (what ought to be).'),
  ('Ceteris paribus', 'a Latin term meaning "other things being equal/held constant," used to isolate the effect of one variable.'),
  ('Short run', 'the time period in which at least one factor of production is fixed.'),
  ('Long run', 'the time period in which all factors of production are variable.'),
  ('Very long run', 'the time period in which technology, population and institutions can change.'),
  ('Land', 'all natural resources used in production (e.g. raw materials, minerals, agricultural land); its reward is rent.'),
  ('Labour', 'the physical and mental human effort used in production; its reward is wages.'),
  ('Capital', 'man-made resources used to produce other goods and services (machinery, buildings, infrastructure); its reward is interest.'),
  ('Enterprise (entrepreneurship)', 'the factor that organises the other factors of production and bears risk; its reward is profit.'),
  ('Human capital', 'the skills, knowledge, training and experience embodied in workers that raise their productivity.'),
  ('Physical capital', 'man-made, tangible assets used in production, such as machinery and buildings.'),
  ('Division of labour', 'breaking a production process into separate tasks performed by different workers.'),
  ('Specialisation', 'concentrating on producing a narrow range of goods/services or tasks in which one has a comparative advantage.'),
  ('Entrepreneur', 'an individual who takes on the risk of organising factors of production to produce goods/services in search of profit.'),
  ('Market economy', 'an economic system in which resource allocation decisions are made through the price mechanism, with minimal government intervention.'),
  ('Planned (command) economy', 'an economic system in which the government/state makes all resource allocation decisions.'),
  ('Mixed economy', 'an economic system combining elements of market and planned economies, with both private markets and government intervention.'),
  ('Production possibility curve (PPC)', 'a diagram showing the maximum combinations of two goods/services an economy can produce with given resources and technology, assuming full and efficient use of resources.'),
  ('Constant opportunity cost', 'where the PPC is a straight line, meaning the same amount of one good must always be given up to produce an extra unit of another.'),
  ('Increasing opportunity cost', 'where the PPC is concave (bowed outward from the origin), meaning progressively more of one good must be given up to produce additional units of another.'),
  ('Outward shift of the PPC', 'represents economic growth, caused by an increase in resources or improved technology.'),
  ('Inward shift of the PPC', 'represents a fall in productive potential, e.g. due to loss of resources or a disaster.'),
  ('Point inside the PPC', 'represents unemployment or underutilisation of resources (productive inefficiency).'),
  ('Point on the PPC', 'represents full and efficient use of resources.'),
  ('Point outside the PPC', 'currently unattainable given existing resources and technology.'),
  ('Free goods', 'goods that have no opportunity cost because they are not scarce (e.g. air).'),
  ('Private (economic) goods', 'goods that are excludable and rivalrous, provided through the market; they have an opportunity cost.'),
  ('Public goods', 'goods that are non-excludable and non-rivalrous, so the free market will fail to provide them (e.g. street lighting, national defence).'),
  ('Non-excludability', 'it is impossible to prevent people who have not paid from consuming a good.'),
  ('Non-rivalry', 'one person''s consumption does not reduce the amount available for others.'),
  ('Free-rider problem', 'occurs when people benefit from a good without paying for it, discouraging private provision.'),
  ('Merit goods', 'goods that are under-consumed relative to the socially optimal level because consumers underestimate their benefits (due to imperfect information), e.g. education, healthcare.'),
  ('Demerit goods', 'goods that are over-consumed relative to the socially optimal level because consumers underestimate their costs/harms, e.g. tobacco, alcohol.'),
  ('Demand', 'the quantity of a good/service that consumers are willing and able to buy at a given price over a given time period.'),
  ('Effective demand', 'demand that is backed by the ability to pay (as opposed to mere desire).'),
  ('Law of demand', 'as price rises, quantity demanded falls, ceteris paribus (inverse relationship).'),
  ('Individual demand', 'the demand of a single consumer for a good.'),
  ('Market demand', 'the sum of all individual demands for a good in a market.'),
  ('Supply', 'the quantity of a good/service that producers are willing and able to sell at a given price over a given time period.'),
  ('Law of supply', 'as price rises, quantity supplied rises, ceteris paribus (direct relationship).'),
  ('Determinants of demand', 'factors other than price affecting demand: income, tastes/preferences, prices of substitutes/complements, population, advertising, expectations.'),
  ('Determinants of supply', 'factors other than price affecting supply: costs of production, technology, number of producers, government taxes/subsidies, weather (for agriculture), expectations.'),
  ('Shift in the demand curve', 'a movement of the whole curve caused by a change in a non-price determinant of demand.'),
  ('Shift in the supply curve', 'a movement of the whole curve caused by a change in a non-price determinant of supply.'),
  ('Movement along a curve (extension/contraction)', 'caused only by a change in the good''s own price.'),
  ('Price elasticity of demand (PED)', 'the responsiveness of quantity demanded to a change in the price of the good itself. PED = %ΔQd / %ΔP.'),
  ('Income elasticity of demand (YED)', 'the responsiveness of quantity demanded to a change in consumer income. YED = %ΔQd / %ΔY.'),
  ('Cross elasticity of demand (XED)', 'the responsiveness of quantity demanded of one good to a change in the price of another good. XED = %ΔQd of A / %ΔP of B.'),
  ('Perfectly elastic demand', 'PED = infinity; quantity demanded falls to zero for any price rise (horizontal curve).'),
  ('Perfectly inelastic demand', 'PED = 0; quantity demanded does not change regardless of price (vertical curve).'),
  ('Unitary elasticity', 'PED (or YED/XED) = 1 (ignoring sign); percentage change in quantity equals percentage change in the variable.'),
  ('Elastic demand', 'PED > 1; quantity demanded changes proportionately more than price.'),
  ('Inelastic demand', 'PED < 1; quantity demanded changes proportionately less than price.'),
  ('Normal good', 'a good with positive YED; demand rises as income rises.'),
  ('Inferior good', 'a good with negative YED; demand falls as income rises.'),
  ('Luxury good', 'a normal good with YED > 1.'),
  ('Necessity good', 'a normal good with YED between 0 and 1.'),
  ('Substitute goods', 'goods with positive XED; a rise in the price of one increases demand for the other.'),
  ('Complementary goods', 'goods with negative XED; a rise in the price of one decreases demand for the other.'),
  ('Total expenditure/revenue', 'price multiplied by quantity; its response to a price change depends on PED.'),
  ('Price elasticity of supply (PES)', 'the responsiveness of quantity supplied to a change in price. PES = %ΔQs / %ΔP.'),
  ('Perfectly elastic supply', 'PES = infinity (horizontal supply curve).'),
  ('Perfectly inelastic supply', 'PES = 0 (vertical supply curve).'),
  ('Factors affecting PES', 'spare capacity, ease of factor substitution, time period, ability to store output, length of production period.'),
  ('Market equilibrium', 'the price and quantity at which quantity demanded equals quantity supplied; no tendency for price to change.'),
  ('Disequilibrium', 'a situation where quantity demanded and quantity supplied are not equal, causing excess demand or excess supply.'),
  ('Excess demand (shortage)', 'occurs when price is below equilibrium; quantity demanded exceeds quantity supplied.'),
  ('Excess supply (surplus)', 'occurs when price is above equilibrium; quantity supplied exceeds quantity demanded.'),
  ('Joint demand (complements)', 'goods demanded together, so a change in demand for one affects demand for the other.'),
  ('Alternative demand (substitutes)', 'goods that can be used in place of one another.'),
  ('Derived demand', 'demand for a good/factor that arises from demand for another good (e.g. demand for labour derived from demand for the product it makes).'),
  ('Joint supply', 'occurs when production of one good automatically results in production of another (e.g. beef and leather).'),
  ('Rationing function of price', 'price allocates scarce goods to those willing and able to pay.'),
  ('Signalling function of price', 'price changes convey information about relative scarcity/preferences to producers and consumers.'),
  ('Incentive function of price', 'price changes provide incentives for producers/consumers to change behaviour.'),
  ('Consumer surplus', 'the difference between what consumers are willing to pay for a good and what they actually pay; the area below the demand curve and above the price.'),
  ('Producer surplus', 'the difference between what producers actually receive for a good and the minimum they would accept; the area above the supply curve and below the price.'),
  ('Market failure', 'a situation in which the free market fails to allocate resources efficiently, leading to a net welfare loss.'),
  ('Non-provision of public goods', 'the free market fails to provide public goods due to the free-rider problem.'),
  ('Price control', 'government intervention to set prices above or below the market equilibrium.'),
  ('Indirect tax', 'a tax on spending/expenditure, paid to the government by producers but often passed on to consumers (e.g. specific tax, ad valorem tax).'),
  ('Specific tax', 'a fixed amount of tax per unit of a good.'),
  ('Incidence of tax', 'the distribution of the tax burden between consumers and producers, depending on relative PED and PES.'),
  ('Subsidy', 'a payment by the government to producers to lower production costs and encourage output/consumption.'),
  ('Direct provision', 'the government itself produces and supplies goods/services (e.g. public healthcare).'),
  ('Maximum price (price ceiling)', 'a legally imposed price set below equilibrium to make a good more affordable; can cause excess demand/shortages.'),
  ('Minimum price (price floor)', 'a legally imposed price set above equilibrium to protect producers/workers; can cause excess supply/surplus.'),
  ('Buffer stock scheme', 'a scheme where the government buys surplus output when price is low (stores it) and sells stock when price is high, to stabilise prices.'),
  ('Provision of information', 'government action to correct imperfect information in markets (e.g. health warnings, labelling).'),
  ('Income', 'a flow of earnings (wages, rent, interest, profit) received over a period of time.'),
  ('Wealth', 'a stock of assets owned at a point in time (e.g. property, savings, shares).'),
  ('Gini coefficient', 'a measure of income/wealth inequality ranging from 0 (perfect equality) to 1 (perfect inequality), derived from the Lorenz curve.'),
  ('Minimum wage', 'a legally imposed wage floor set above the equilibrium wage to raise low incomes.'),
  ('Transfer payments', 'payments made by the government to individuals for which no good/service is exchanged (e.g. benefits, pensions).'),
  ('Progressive tax', 'a tax where the average rate of tax rises as income rises.'),
  ('Inheritance tax', 'a tax on wealth transferred upon death.'),
  ('Capital tax', 'a tax on wealth or capital gains.'),
  ('National income', 'the total value of output, income or expenditure of an economy over a period, typically a year.'),
  ('Gross Domestic Product (GDP)', 'the total value of goods and services produced within a country''s borders in a given period.'),
  ('Gross National Income (GNI)', 'GDP plus net income earned by residents from overseas investments (minus income paid to foreign residents).'),
  ('Net National Income (NNI)', 'GNI minus depreciation (capital consumption).'),
  ('Market prices', 'values that include indirect taxes and exclude subsidies.'),
  ('Basic prices', 'values that exclude indirect taxes and include subsidies (reflecting what producers actually receive).'),
  ('Gross values', 'values that do not account for depreciation of capital.'),
  ('Net values', 'values that subtract depreciation of capital from gross values.'),
  ('Depreciation (capital consumption)', 'the fall in value of capital assets due to wear and tear/obsolescence.'),
  ('Circular flow of income', 'a model showing the flow of income and expenditure between households, firms, government and the international economy.'),
  ('Closed economy', 'an economy with no interaction (trade) with the rest of the world.'),
  ('Open economy', 'an economy that trades with other countries.'),
  ('Injections', 'additions to the circular flow of income: investment (I), government spending (G), exports (X).'),
  ('Leakages/withdrawals', 'income removed from the circular flow: savings (S), taxation (T), imports (M).'),
  ('Equilibrium national income', 'the level of income where injections equal leakages (or planned aggregate demand equals planned output).'),
  ('Aggregate Demand (AD)', 'the total demand for goods and services in an economy at a given price level over a given time period.'),
  ('AD = C + I + G + (X − M)', 'consumption + investment + government spending + net exports.'),
  ('Consumption (C)', 'total spending by households on goods and services.'),
  ('Investment (I)', 'spending by firms on capital goods.'),
  ('Government spending (G)', 'spending by the public sector on goods and services.'),
  ('Net exports (X − M)', 'exports minus imports.'),
  ('Aggregate Supply (AS)', 'the total output of goods and services that firms in an economy are willing and able to produce at a given price level.'),
  ('Short-run Aggregate Supply (SRAS)', 'total output supplied in the period when at least one factor input (e.g. wages) is fixed; upward sloping.'),
  ('Long-run Aggregate Supply (LRAS)', 'total output supplied when all factor inputs are variable; often shown as vertical at full-employment output (or as three sections in Keynesian analysis).'),
  ('Macroeconomic equilibrium', 'the price level and real output at which AD equals AS.'),
  ('Economic growth', 'an increase in the real output (real GDP) of an economy over time.'),
  ('Nominal GDP', 'GDP measured in current prices, not adjusted for inflation.'),
  ('Real GDP', 'GDP adjusted for inflation, reflecting the actual volume of output.'),
  ('Unemployment', 'a situation where people who are willing and able to work, and are actively seeking work, cannot find a job.'),
  ('Unemployment rate', 'the percentage of the labour force that is unemployed.'),
  ('Frictional unemployment', 'short-term unemployment that occurs when people are between jobs.'),
  ('Structural unemployment', 'unemployment caused by a mismatch of skills/location due to changes in the structure of the economy (decline of an industry).'),
  ('Cyclical (demand-deficient) unemployment', 'unemployment caused by a fall in aggregate demand during a downturn/recession.'),
  ('Seasonal unemployment', 'unemployment caused by seasonal changes in demand for labour.'),
  ('Technological unemployment', 'unemployment caused by workers being replaced by machinery/automation.'),
  ('Inflation', 'a sustained/persistent rise in the general price level of an economy over time.'),
  ('Deflation', 'a sustained/persistent fall in the general price level.'),
  ('Disinflation', 'a fall in the rate of inflation (prices still rising, but more slowly).'),
  ('Consumer Price Index (CPI)', 'a measure of the average change in prices of a representative basket of goods and services purchased by households.'),
  ('Nominal values', 'values measured in current, money terms.'),
  ('Real values', 'values adjusted for inflation.'),
  ('Cost-push inflation', 'inflation caused by a rise in production costs (e.g. wages, raw materials), shifting AS left.'),
  ('Demand-pull inflation', 'inflation caused by excessive aggregate demand relative to aggregate supply.'),
  ('Macroeconomic policy objectives', 'government goals typically including price stability, low unemployment and economic growth.'),
  ('Fiscal policy', 'the use of government spending and taxation to influence aggregate demand and achieve macroeconomic objectives.'),
  ('Government budget', 'a statement of planned government spending and revenue (mainly taxation) over a period.'),
  ('Budget deficit', 'a situation where government spending exceeds government revenue.'),
  ('Budget surplus', 'a situation where government revenue exceeds government spending.'),
  ('National debt', 'the total accumulated amount owed by the government as a result of past budget deficits.'),
  ('Direct tax', 'a tax levied directly on income or wealth, paid directly to the government by the taxpayer (e.g. income tax).'),
  ('Indirect tax', 'a tax on spending/goods and services.'),
  ('Progressive tax', 'average tax rate rises as income rises.'),
  ('Regressive tax', 'average tax rate falls as income rises.'),
  ('Proportional tax', 'average tax rate stays constant as income changes.'),
  ('Marginal rate of tax (mrt)', 'the proportion of an additional unit of income paid in tax.'),
  ('Average rate of tax (art)', 'total tax paid divided by total income.'),
  ('Capital spending (investment spending)', 'government spending on long-term assets/infrastructure.'),
  ('Current spending', 'government spending on day-to-day items (e.g. wages, supplies).'),
  ('Expansionary fiscal policy', 'increased government spending and/or reduced taxation to raise AD.'),
  ('Contractionary fiscal policy', 'reduced government spending and/or increased taxation to reduce AD.'),
  ('Monetary policy', 'the use of interest rates, money supply and credit regulations by the central bank/government to influence AD and macroeconomic objectives.'),
  ('Interest rate', 'the cost of borrowing money or the reward for saving money, expressed as a percentage.'),
  ('Money supply', 'the total stock of money circulating in an economy.'),
  ('Credit regulations', 'rules governing the availability and terms of borrowing/lending.'),
  ('Expansionary monetary policy', 'lower interest rates and/or increased money supply to raise AD.'),
  ('Contractionary monetary policy', 'higher interest rates and/or reduced money supply to reduce AD.'),
  ('Supply-side policy', 'government policy aimed at increasing the productive capacity/potential output of an economy by shifting LRAS to the right.'),
  ('Productivity', 'output per unit of input (e.g. output per worker).'),
  ('Productive capacity', 'the maximum output an economy can produce with existing resources.'),
  ('Absolute advantage', 'the ability of a country to produce a good using fewer resources (more efficiently) than another country.'),
  ('Comparative advantage', 'the ability of a country to produce a good at a lower opportunity cost than another country.'),
  ('Specialisation (international)', 'countries concentrating on producing goods in which they have a comparative advantage.'),
  ('Free trade', 'trade between countries without any government-imposed restrictions.'),
  ('Trade liberalisation', 'the process of reducing barriers to international trade.'),
  ('Trading possibility curve', 'a curve showing the combinations of goods a country can consume after specialisation and trade, lying outside its PPC.'),
  ('Terms of trade', 'the ratio of a country''s average export prices to its average import prices, indicating the rate at which exports exchange for imports.'),
  ('Protectionism', 'government policies restricting free trade to protect domestic industries.'),
  ('Tariff', 'a tax imposed on imported goods.'),
  ('Import quota', 'a physical limit on the quantity of a good that can be imported.'),
  ('Export subsidy', 'a payment by government to domestic producers to encourage exports.'),
  ('Embargo', 'a complete ban on trade (imports or exports) with a particular country or of a particular good.'),
  ('Administrative burden ("red tape")', 'bureaucratic/regulatory requirements that make importing more difficult or costly.'),
  ('Balance of payments', 'a record of all financial transactions between a country''s residents and the rest of the world.'),
  ('Current account', 'the section of the balance of payments recording trade in goods, trade in services, primary income and secondary income.'),
  ('Trade in goods', 'exports minus imports of physical/tangible products.'),
  ('Trade in services', 'exports minus imports of intangible services (e.g. tourism, finance).'),
  ('Primary income', 'income flows from investment (interest, profits, dividends) and employment abroad.'),
  ('Secondary income', 'transfers such as remittances, foreign aid and grants with no good/service exchanged.'),
  ('Current account deficit', 'occurs when outflows on the current account exceed inflows.'),
  ('Current account surplus', 'occurs when inflows on the current account exceed outflows.'),
  ('Exchange rate', 'the price of one currency expressed in terms of another currency.'),
  ('Floating exchange rate', 'an exchange rate determined solely by the forces of demand and supply for a currency, with no government intervention.'),
  ('Depreciation', 'a fall in the value of a floating currency against other currencies.'),
  ('Appreciation', 'a rise in the value of a floating currency against other currencies.'),
  ('Expenditure-switching policy', 'policy aimed at shifting demand between domestic and foreign goods (e.g. tariffs, depreciation).'),
  ('Expenditure-reducing policy', 'policy aimed at reducing overall spending in the economy (e.g. contractionary fiscal/monetary policy) to reduce imports.'),
  ('Utility', 'the satisfaction/benefit a consumer derives from consuming a good or service.'),
  ('Total utility (TU)', 'the total satisfaction gained from consuming a given quantity of a good.'),
  ('Marginal utility (MU)', 'the additional satisfaction gained from consuming one more unit of a good.'),
  ('Law of diminishing marginal utility', 'as more units of a good are consumed, the additional (marginal) utility from each extra unit eventually declines.'),
  ('Equi-marginal principle', 'consumers maximise total utility by allocating spending so that the marginal utility per dollar spent is equal across all goods.'),
  ('Indifference curve', 'a curve showing all combinations of two goods that give a consumer the same level of total utility/satisfaction.'),
  ('Budget line', 'a line showing all combinations of two goods a consumer can afford, given income and prices.'),
  ('Income effect', 'the change in quantity demanded resulting from a change in real income caused by a price change.'),
  ('Substitution effect', 'the change in quantity demanded resulting from a change in the relative price of a good compared to substitutes.'),
  ('Giffen good', 'an inferior good for which the income effect outweighs the substitution effect, so quantity demanded rises as price rises (upward-sloping demand curve).'),
  ('Productive efficiency', 'occurs when output is produced at the lowest possible cost (on the production possibility curve / at the minimum point of the average cost curve).'),
  ('Allocative efficiency', 'occurs when resources are allocated so that price equals marginal cost (P = MC), reflecting consumer preferences.'),
  ('Pareto optimality', 'a situation where resources are allocated such that no one can be made better off without making someone else worse off.'),
  ('Dynamic efficiency', 'efficiency achieved over time through innovation and investment, improving products/processes.'),
  ('Market failure', 'occurs when the free market fails to allocate resources efficiently, resulting in a net welfare loss to society.'),
  ('Private costs', 'costs incurred directly by individuals/firms involved in an economic activity.'),
  ('Private benefits', 'benefits received directly by individuals/firms involved in an economic activity.'),
  ('External costs', 'costs of an economic activity borne by third parties not directly involved.'),
  ('External benefits', 'benefits of an economic activity received by third parties not directly involved.'),
  ('Social cost', 'the total cost of an activity to society = private cost + external cost.'),
  ('Social benefit', 'the total benefit of an activity to society = private benefit + external benefit.'),
  ('Externality', 'a spillover effect (cost or benefit) of production/consumption affecting third parties, not reflected in market prices.'),
  ('Positive externality', 'a beneficial spillover effect on third parties (e.g. education).'),
  ('Negative externality', 'a harmful spillover effect on third parties (e.g. pollution).'),
  ('Deadweight welfare loss', 'the net loss of economic welfare to society caused by market failure (e.g. resulting from externalities).'),
  ('Asymmetric information', 'a situation where one party to a transaction has more/better information than the other.'),
  ('Moral hazard', 'a situation where one party takes on more risk because they do not bear the full costs of that risk (often due to insurance or asymmetric information).'),
  ('Fixed factors of production', 'inputs that cannot be changed in the short run.'),
  ('Variable factors of production', 'inputs that can be changed in the short run.'),
  ('Total product', 'the total output produced by a firm using a given quantity of factors.'),
  ('Average product', 'total product divided by the quantity of the variable factor employed.'),
  ('Marginal product', 'the additional output produced by employing one more unit of the variable factor.'),
  ('Law of diminishing returns (law of variable proportions)', 'as more units of a variable factor are added to a fixed factor, the marginal product of the variable factor will eventually decline.'),
  ('Fixed costs (FC)', 'costs that do not vary with output in the short run.'),
  ('Variable costs (VC)', 'costs that vary directly with the level of output.'),
  ('Total cost (TC)', 'the sum of fixed costs and variable costs (TC = FC + VC).'),
  ('Average cost (AC)', 'total cost divided by output (AC = TC/Q).'),
  ('Marginal cost (MC)', 'the additional cost of producing one more unit of output.'),
  ('Average total cost (ATC)', 'total cost per unit of output.'),
  ('Average fixed cost (AFC)', 'fixed cost per unit of output.'),
  ('Average variable cost (AVC)', 'variable cost per unit of output.'),
  ('Returns to scale', 'the proportionate change in output resulting from a proportionate change in all factor inputs in the long run.'),
  ('Long-run average cost (LRAC) curve', 'shows the lowest average cost of producing each level of output when all factors are variable.'),
  ('Minimum efficient scale (MES)', 'the lowest level of output at which a firm can minimise its long-run average costs.'),
  ('Economies of scale', 'factors causing average cost to fall as output increases in the long run.'),
  ('Internal economies of scale', 'cost savings arising within a firm as it grows (e.g. technical, managerial, financial, marketing, purchasing/bulk-buying, risk-bearing).'),
  ('External economies of scale', 'cost savings arising from the growth of the whole industry, benefiting all firms within it.'),
  ('Diseconomies of scale', 'factors causing average cost to rise as output increases beyond a certain point.'),
  ('Internal diseconomies of scale', 'rising average costs arising within a firm as it grows too large (e.g. management/coordination problems).'),
  ('External diseconomies of scale', 'rising average costs arising from the growth of the whole industry (e.g. congestion, competition for resources).'),
  ('Total revenue (TR)', 'total income received from sales (price × quantity).'),
  ('Average revenue (AR)', 'revenue per unit sold (equals price for a single-price firm).'),
  ('Marginal revenue (MR)', 'the additional revenue from selling one more unit of output.'),
  ('Normal profit', 'the minimum level of profit needed to keep a firm/entrepreneur in its current line of business (treated as a cost of production).'),
  ('Subnormal profit', 'profit below normal profit (a loss situation in economic terms).'),
  ('Supernormal (abnormal) profit', 'profit in excess of normal profit.'),
  ('Perfect competition', 'a market structure with many buyers/sellers, homogeneous products, free entry/exit and perfect information.'),
  ('Imperfect competition', 'any market structure that does not meet the conditions of perfect competition.'),
  ('Monopoly', 'a market structure with a single seller/dominant firm and significant barriers to entry.'),
  ('Monopolistic competition', 'a market structure with many firms, differentiated products and relatively free entry/exit.'),
  ('Oligopoly', 'a market structure dominated by a few large firms, often with interdependent decision-making.'),
  ('Natural monopoly', 'a market where economies of scale are so significant that a single firm can supply the entire market at a lower cost than multiple firms.'),
  ('Barriers to entry', 'obstacles preventing new firms from entering a market (legal, market, cost, physical).'),
  ('Legal barriers', 'barriers such as patents, licences and copyrights that restrict entry.'),
  ('Market barriers', 'barriers such as brand loyalty and control of distribution channels.'),
  ('Cost barriers', 'barriers such as high sunk/start-up costs or economies of scale enjoyed by incumbents.'),
  ('Physical barriers', 'barriers such as limited availability of essential resources or space.'),
  ('Shutdown price', 'the price below which a firm will stop producing because revenue does not cover variable costs (short run) or total costs (long run).'),
  ('Contestable market', 'a market with low barriers to entry and exit (including low sunk costs), where the threat of new entrants disciplines incumbent firms.'),
  ('Price competition', 'firms competing by altering price.'),
  ('Non-price competition', 'firms competing through means other than price (e.g. advertising, branding, quality).'),
  ('Collusion', 'an agreement between firms to coordinate behaviour (e.g. fix prices or output) to reduce competition.'),
  ('Prisoner''s Dilemma', 'a game theory model showing that individual firms may rationally choose not to cooperate (collude) even though cooperation would benefit both, due to mutual distrust.'),
  ('Concentration ratio', 'the proportion of total market output/sales accounted for by a given number (e.g. top 4 or top 5) of the largest firms in an industry.'),
  ('Internal (organic) growth', 'growth achieved by expanding a firm''s own output/capacity internally.'),
  ('Diversification', 'expanding into new markets or products, often to spread risk.'),
  ('External growth', 'growth achieved through merging with or acquiring other firms.'),
  ('Merger/takeover (integration)', 'the combination of two or more firms into one.'),
  ('Horizontal integration', 'merger between firms at the same stage of production in the same industry.'),
  ('Vertical integration', 'merger between firms at different stages of production in the same industry.'),
  ('Forward vertical integration', 'merger with a firm closer to the final consumer.'),
  ('Backward vertical integration', 'merger with a firm closer to the source of raw materials.'),
  ('Conglomerate integration', 'merger between firms in unrelated industries.'),
  ('Cartel', 'a formal agreement among firms in an industry to collude on price and/or output to maximise joint profits.'),
  ('Principal–agent problem', 'a conflict of interest arising when the objectives of owners/shareholders (principals) differ from those of managers (agents) who run the firm.'),
  ('Profit maximisation', 'the traditional objective of firms, achieved where marginal revenue equals marginal cost (MR = MC).'),
  ('Survival', 'a firm''s objective of remaining in business, often prioritised during difficult trading conditions.'),
  ('Profit satisficing', 'aiming for an acceptable, rather than maximum, level of profit.'),
  ('Sales maximisation', 'aiming to maximise total revenue rather than profit.'),
  ('Revenue maximisation', 'producing at the output where marginal revenue equals zero.'),
  ('Price discrimination', 'charging different prices to different consumers/groups for the same good, not justified by cost differences.'),
  ('First-degree price discrimination', 'charging each consumer the maximum price they are willing to pay.'),
  ('Second-degree price discrimination', 'charging different prices based on the quantity consumed (e.g. bulk discounts).'),
  ('Third-degree price discrimination', 'charging different prices to different identifiable groups/markets.'),
  ('Limit pricing', 'setting a low price to deter potential new entrants from entering the market.'),
  ('Predatory pricing', 'deliberately setting a very low (or below-cost) price to force rivals out of the market.'),
  ('Price leadership', 'a pricing pattern where one dominant firm sets the price and other firms follow.'),
  ('Kinked demand curve', 'a model of oligopoly demand showing price rigidity, based on the assumption rivals follow price cuts but not price rises.'),
  ('Ad valorem tax', 'a tax charged as a percentage of the price of a good.'),
  ('Production quota', 'a government-imposed limit on the quantity of a good that can be produced.'),
  ('Prohibition', 'a complete legal ban on the production/sale/consumption of a good.'),
  ('Licence', 'legal permission required to produce, sell or consume certain goods, used to restrict market activity.'),
  ('Regulation', 'rules imposed by government to control the behaviour of firms/individuals in a market.'),
  ('Deregulation', 'the removal or reduction of government rules/regulations in a market.'),
  ('Pollution permit', 'a tradeable licence allowing a firm to emit a certain amount of pollution, used to control negative externalities.'),
  ('Property rights', 'legal rights of ownership that allow the private allocation and enforcement of resource use, used to internalise externalities.'),
  ('Nationalisation', 'transfer of ownership of firms/industries from the private sector to the government.'),
  ('Privatisation', 'transfer of ownership of firms/industries from the government to the private sector.'),
  ('Behavioural insights/"nudge" theory', 'using an understanding of psychological biases to design policies that encourage (without forcing) people to make certain choices.'),
  ('Government failure', 'a situation where government intervention in a market leads to a net welfare loss, i.e. a misallocation of resources worse than before intervention.'),
  ('Equity', 'fairness in the distribution of income/wealth/opportunities (a normative concept).'),
  ('Equality', 'an identical/equal distribution of income, wealth or opportunities.'),
  ('Absolute poverty', 'a situation where individuals lack the minimum income/resources needed to meet basic needs.'),
  ('Relative poverty', 'a situation where individuals have significantly less income/wealth than the average in their society.'),
  ('Poverty trap', 'a situation where increases in earned income are offset by a loss of benefits and/or increased taxes, discouraging work.'),
  ('Negative income tax', 'a tax/benefit system in which those earning below a threshold receive a payment from the government instead of paying tax.'),
  ('Universal benefits', 'benefits paid to everyone in a category regardless of income.'),
  ('Means-tested benefits', 'benefits paid only to those whose income/wealth falls below a specified level.'),
  ('Universal basic income (UBI)', 'a regular, unconditional cash payment given to all citizens regardless of other income.'),
  ('Derived demand (for labour)', 'demand for labour that arises from the demand for the goods/services labour produces.'),
  ('Marginal revenue product (MRP)', 'the additional revenue generated by employing one more unit of a factor of production (MRP = MPP × MR).'),
  ('Wage and non-wage factors', 'wage factors are pay-related; non-wage factors include working conditions, job satisfaction and fringe benefits, which affect labour supply.'),
  ('Trade union', 'an organisation of workers that negotiates collectively with employers over wages and conditions.'),
  ('National minimum wage', 'a legally binding minimum wage set by the government.'),
  ('Monopsony', 'a market with a single (or dominant) buyer of a good or factor, such as labour.'),
  ('Wage differentials', 'differences in wages paid to different workers/occupations, determined by labour market forces.'),
  ('Transfer earnings', 'the minimum payment required to keep a factor of production in its current use (its opportunity cost).'),
  ('Economic rent', 'any payment to a factor of production above its transfer earnings.'),
  ('Multiplier', 'the ratio of a change in equilibrium national income to the initial change in injections (spending) that caused it.'),
  ('Average propensity to save (APS)', 'the proportion of total income that is saved.'),
  ('Marginal propensity to save (MPS)', 'the proportion of an additional unit of income that is saved.'),
  ('Average propensity to consume (APC)', 'the proportion of total income that is spent on consumption.'),
  ('Marginal propensity to consume (MPC)', 'the proportion of an additional unit of income that is spent on consumption.'),
  ('Average propensity to import (APM)', 'the proportion of total income spent on imports.'),
  ('Marginal propensity to import (MPM)', 'the proportion of an additional unit of income spent on imports.'),
  ('Consumption function', 'the relationship between the level of consumption and the level of income.'),
  ('Autonomous consumption', 'consumption that occurs independent of the level of income.'),
  ('Induced consumption', 'consumption that varies directly with the level of income.'),
  ('Savings function', 'the relationship between the level of saving and the level of income.'),
  ('Autonomous investment', 'investment unrelated to the current level of income/output.'),
  ('Induced investment', 'investment that varies with the level of income/output.'),
  ('Accelerator (accelerator theory)', 'the theory that the level of investment depends on the rate of change of national income/output (rather than its level).'),
  ('Full employment level of national income', 'the level of national income at which all available resources are fully employed.'),
  ('Inflationary gap', 'occurs when planned aggregate expenditure exceeds the full-employment level of output, creating excess demand and pushing up prices.'),
  ('Deflationary (recessionary) gap', 'occurs when planned aggregate expenditure is below the full-employment level of output, leaving resources unemployed.'),
  ('Actual growth', 'the real, measured increase in an economy''s real GDP over a period.'),
  ('Potential growth', 'the increase in an economy''s productive capacity (maximum possible output).'),
  ('Output gap', 'the difference between actual output and potential output.'),
  ('Positive output gap', 'occurs when actual output exceeds potential output (economy overheating).'),
  ('Negative output gap', 'occurs when actual output is below potential output (spare capacity).'),
  ('Business (trade) cycle', 'the fluctuation of an economy''s real output around its long-run trend, through phases of boom, downturn/recession, trough and recovery.'),
  ('Automatic stabilisers', 'features of fiscal policy (e.g. progressive taxes, unemployment benefits) that automatically reduce fluctuations in the business cycle without new government action.'),
  ('Inclusive economic growth', 'economic growth in which the benefits are widely shared across society, reducing inequality.'),
  ('Sustainable economic growth', 'economic growth that meets the needs of the present without compromising the ability of future generations to meet their own needs.'),
  ('Full employment', 'a situation where all those willing and able to work at the going wage rate can find employment (though frictional/structural unemployment may still exist).'),
  ('Equilibrium unemployment', 'unemployment that exists even when the labour market is in equilibrium (i.e. voluntary unemployment, the natural rate).'),
  ('Disequilibrium unemployment', 'unemployment caused by the labour market not being in equilibrium (e.g. real wages above the equilibrium level), including cyclical unemployment.'),
  ('Hysteresis', 'the persistence of high unemployment even after the original cause has been removed, often due to skill loss/lower employability of the long-term unemployed.'),
  ('Voluntary unemployment', 'unemployment where individuals choose not to work at the current wage rate.'),
  ('Involuntary unemployment', 'unemployment where individuals want to work at the current wage rate but cannot find a job.'),
  ('Natural rate of unemployment', 'the rate of unemployment that exists when the labour market is in equilibrium, consisting of frictional and structural unemployment.'),
  ('Geographical mobility of labour', 'the ease with which workers can move between different locations for work.'),
  ('Occupational mobility of labour', 'the ease with which workers can move between different jobs/occupations.'),
  ('Money', 'anything generally accepted as a medium of exchange; functions include medium of exchange, unit of account, store of value and standard for deferred payment.'),
  ('Money supply', 'the total quantity of money in circulation in an economy.'),
  ('Quantity theory of money', 'the theory that the general price level is directly related to the quantity of money in circulation, expressed as MV = PT (money supply × velocity of circulation = price level × transactions).'),
  ('Commercial bank', 'a financial institution that accepts deposits and provides loans to individuals and businesses.'),
  ('Demand deposit account', 'a bank account from which money can be withdrawn on demand.'),
  ('Reserve ratio', 'the proportion of a bank''s deposits held as liquid reserves rather than lent out.'),
  ('Capital ratio', 'the proportion of a bank''s assets funded by its own capital rather than debt.'),
  ('Credit creation', 'the process by which commercial banks expand the money supply through lending.'),
  ('Bank credit multiplier', 'the amount by which an initial deposit is multiplied through the banking system''s lending activity.'),
  ('Central bank', 'the institution responsible for a country''s monetary policy, issuing currency and regulating the banking system.'),
  ('Government deficit financing', 'borrowing by the government to fund a budget deficit, which can increase the money supply.'),
  ('Quantitative easing (QE)', 'a monetary policy tool where a central bank creates new money to buy financial assets, increasing the money supply.'),
  ('Liquidity preference theory', 'the theory that the demand for money depends on the desire to hold money for transactions, precautionary and speculative motives.'),
  ('Loanable funds theory', 'the theory that the interest rate is determined by the demand for and supply of loanable funds (savings and borrowing).'),
  ('Macroeconomic policy objectives (A Level)', 'price stability, balance of payments equilibrium, low unemployment, economic growth, development, sustainability and equitable redistribution of income/wealth.'),
  ('Internal value of money', 'the purchasing power of money within a domestic economy (inversely related to inflation).'),
  ('External value of money', 'the value of a currency in terms of other currencies (the exchange rate).'),
  ('Phillips curve', 'a model showing an inverse (trade-off) relationship between the rate of unemployment and the rate of inflation.'),
  ('Expectations-augmented Phillips curve', 'a modification of the Phillips curve showing that in the long run there is no trade-off between unemployment and inflation once expectations adjust, giving a vertical long-run Phillips curve at the natural rate of unemployment.'),
  ('Laffer curve', 'a curve showing the relationship between tax rates and total tax revenue, illustrating that beyond a certain point higher tax rates can reduce total revenue.'),
  ('Market-based supply-side policy', 'policy that relies on reducing government intervention/regulation to increase incentives and efficiency (e.g. tax cuts, deregulation).'),
  ('Interventionist supply-side policy', 'policy that relies on direct government action to increase productive capacity (e.g. spending on education, infrastructure).'),
  ('Financial account', 'the section of the balance of payments recording flows of investment (FDI, portfolio investment) into and out of a country.'),
  ('Capital account', 'the section of the balance of payments recording capital transfers and transactions in non-produced, non-financial assets.'),
  ('Nominal exchange rate', 'the exchange rate expressed in money terms, not adjusted for price level differences.'),
  ('Real exchange rate', 'the exchange rate adjusted for relative price levels/inflation between two countries.'),
  ('Trade-weighted exchange rate', 'an index measuring the value of a currency against a basket of other currencies, weighted by trade importance.'),
  ('Fixed exchange rate', 'an exchange rate set and maintained by the government/central bank at a particular level against another currency.'),
  ('Managed (dirty) float', 'an exchange rate largely determined by market forces but with occasional government/central bank intervention.'),
  ('Devaluation', 'a deliberate reduction in the value of a fixed exchange rate by the government.'),
  ('Revaluation', 'a deliberate increase in the value of a fixed exchange rate by the government.'),
  ('Marshall-Lerner condition', 'the condition stating that a devaluation/depreciation will improve the current account balance only if the sum of the price elasticities of demand for exports and imports is greater than 1.'),
  ('J-curve effect', 'the pattern where a devaluation/depreciation initially worsens the current account balance before eventually improving it, tracing a J-shaped path over time.'),
  ('Economic development', 'a broad measure of improvement in living standards, including economic growth, health, education and quality of life.'),
  ('Purchasing power parity (PPP)', 'an exchange rate adjustment that equalises the purchasing power of different currencies, enabling fairer international income comparisons.'),
  ('Human Development Index (HDI)', 'a composite index measuring development based on life expectancy, education and income (GNI per capita).'),
  ('Measure of Economic Welfare (MEW)', 'an indicator adjusting GDP for factors affecting welfare not captured by GDP, such as leisure and pollution.'),
  ('Multidimensional Poverty Index (MPI)', 'a composite index measuring poverty based on multiple deprivations (e.g. health, education, living standards), not just income.'),
  ('Kuznets curve', 'a hypothesis suggesting income inequality first increases and then decreases as an economy develops (an inverted-U relationship).'),
  ('Birth rate', 'the number of live births per 1,000 of the population per year.'),
  ('Death rate', 'the number of deaths per 1,000 of the population per year.'),
  ('Infant mortality rate', 'the number of deaths of infants under one year old per 1,000 live births.'),
  ('Net migration', 'the difference between the number of people entering and leaving a country.'),
  ('Optimum population', 'the population size that maximises output/income per head, given available resources and technology.'),
  ('Urbanisation', 'the increasing proportion of a country''s population living in urban (town/city) areas.'),
  ('Lorenz curve', 'a graph showing the cumulative distribution of income/wealth across a population, used to derive the Gini coefficient.'),
  ('Primary sector', 'the part of the economy involved in the extraction of raw materials (e.g. agriculture, mining).'),
  ('Secondary sector', 'the part of the economy involved in manufacturing and construction.'),
  ('Tertiary sector', 'the part of the economy involved in providing services.'),
  ('International aid', 'the transfer of resources (money, goods, technical assistance) from one country/organisation to another to support development.'),
  ('Bilateral aid', 'aid given directly from one country''s government to another.'),
  ('Multilateral aid', 'aid given by several countries through an international organisation (e.g. the World Bank).'),
  ('Multinational company (MNC)', 'a firm that owns/operates production facilities in more than one country.'),
  ('Foreign Direct Investment (FDI)', 'investment by a firm or individual in one country into business interests (e.g. production facilities) in another country.'),
  ('External debt', 'money owed by a country''s government, corporations or citizens to foreign creditors.'),
  ('International Monetary Fund (IMF)', 'an international organisation that promotes global monetary cooperation, financial stability and provides financial assistance to member countries facing balance of payments problems.'),
  ('World Bank', 'an international organisation that provides financial and technical assistance to developing countries for development projects.'),
  ('Globalisation', 'the increasing integration and interdependence of national economies through trade, investment, capital flows, migration and the spread of technology.'),
  ('Free trade area', 'a group of countries that abolish tariffs/trade barriers between themselves but retain independent trade policies with non-members.'),
  ('Customs union', 'a free trade area with, additionally, a common external tariff applied to non-member countries.'),
  ('Monetary union', 'a group of countries that share a common currency and monetary policy.'),
  ('Economic union (full economic union)', 'the deepest form of integration, combining a customs union, free movement of factors of production, common economic policies and often a common currency.'),
  ('Trade creation', 'occurs when trade shifts from a higher-cost domestic producer to a lower-cost producer within a trading bloc, increasing economic welfare.'),
  ('Trade diversion', 'occurs when trade shifts from a lower-cost producer outside a trading bloc to a higher-cost producer within the bloc, due to a common external tariff; can reduce economic welfare.'),
  ('Analyse', 'examine in detail to show meaning, identify elements and the relationship between them.'),
  ('Assess', 'make an informed judgement.'),
  ('Calculate', 'work out from given facts, figures or information.'),
  ('Comment', 'give an informed opinion.'),
  ('Compare', 'identify/comment on similarities and/or differences.'),
  ('Consider', 'review and respond to given information.'),
  ('Define', 'give precise meaning.'),
  ('Demonstrate', 'show how or give an example.'),
  ('Describe', 'state the points of a topic / give characteristics and main features.'),
  ('Discuss', 'write about issue(s) or topic(s) in depth in a structured way.'),
  ('Evaluate', 'judge or calculate the quality, importance, amount or value of something.'),
  ('Explain', 'set out purposes or reasons / make relationships clear / say why and/or how, supported with relevant evidence.'),
  ('Give', 'produce an answer from a given source or recall/memory.'),
  ('Identify', 'name/select/recognise.'),
  ('Justify', 'support a case with evidence/argument.'),
  ('Outline', 'set out the main points.'),
  ('__seed_sentinel__', '')
)
INSERT INTO public.definitions (term, definition_text, source_label)
SELECT trim(s.term), trim(s.definition_text), 'Marginal Economics reviewed glossary'
FROM supplied s
WHERE s.term <> '__seed_sentinel__'
  AND NOT EXISTS (
    SELECT 1 FROM public.definitions d
    WHERE lower(trim(d.term)) = lower(trim(s.term))
      AND trim(d.definition_text) = trim(s.definition_text)
  );

